// Parse incoming request from OpenClaw
// Expected: { youtube_url, topic, user_id }
const body = $input.first().json.body || $input.first().json;

const youtube_url = body.youtube_url || body.url || '';
const topic = body.topic || '';
const user_id = body.user_id || 'default';

if (!youtube_url) {
  throw new Error('youtube_url is required');
}

// Validate it looks like a YouTube URL or search URL
const isValid = youtube_url.includes('youtube.com') || 
                youtube_url.includes('youtu.be') ||
                youtube_url.startsWith('http');

if (!isValid) {
  throw new Error('Invalid YouTube URL: ' + youtube_url);
}

console.log('Pipeline started for:', youtube_url);

return [{
  json: {
    youtube_url,
    topic,
    user_id,
    started_at: new Date().toISOString(),
    run_id: Date.now().toString()
  }
}];

// Parse yt-dlp output — each line is a JSON object
const raw = $input.first().json.stdout || '';
const youtube_url = $('Parse Input').first().json.youtube_url;
const topic = $('Parse Input').first().json.topic;
const user_id = $('Parse Input').first().json.user_id;
const run_id = $('Parse Input').first().json.run_id;

const videos = [];
const lines = raw.trim().split('\n');

for (const line of lines) {
  if (!line.trim()) continue;
  try {
    const v = JSON.parse(line);
    if (v.error) continue;
    videos.push({
      id:          v.id,
      title:       v.title || 'Unknown',
      url:         v.url || `https://youtube.com/watch?v=${v.id}`,
      duration:    v.duration,
      channel:     v.channel || v.uploader || 'Unknown',
      description: (v.description || '').substring(0, 300),
      view_count:  v.view_count,
      upload_date: v.upload_date
    });
  } catch(e) {}
}

if (videos.length === 0) {
  throw new Error('No videos found from yt-dlp');
}

console.log(`Found ${videos.length} videos`);

return [{
  json: {
    videos,
    total: videos.length,
    source_url: youtube_url,
    topic,
    user_id,
    run_id
  }
}];

// For each video, check if it has subtitles/captions
// Uses yt-dlp --list-subs (fast, no download)
const data = $input.first().json;
const videos = data.videos;

// We'll process the first 3 videos only for speed
// You can change this limit
const toProcess = videos.slice(0, 3);

console.log(`Checking subtitles for ${toProcess.length} videos`);

return toProcess.map(v => ({
  json: {
    ...data,
    current_video: v
  }
}));

// Parse subtitle check results and decide path
const video = $('Split Videos').first().json.current_video;
const subsOutput = $('Check Subtitles').first().json.stdout || '';
const captionOutput = $('Download Captions').first().json.stdout || '';
const data = $('Split Videos').first().json;

// Check what we found
const hasManualSubs = subsOutput.includes('Language') && 
                      !subsOutput.includes('has no subtitles');
const hasAutoCaptions = subsOutput.toLowerCase().includes('automatic') || 
                        subsOutput.includes('[auto]');
const hasDescription = (video.description || '').length > 100;
const hasCaptionFile = captionOutput !== 'NO_CAPTIONS' && 
                       captionOutput.length > 50;

// Clean VTT to plain text
function cleanVtt(vtt) {
  if (!vtt || vtt === 'NO_CAPTIONS') return '';
  return vtt
    .split('\n')
    .filter(l => !l.includes('-->') && 
                 !l.startsWith('WEBVTT') && 
                 !l.startsWith('Kind:') &&
                 !l.startsWith('Language:') &&
                 l.trim().length > 0)
    .map(l => l.replace(/<[^>]+>/g, '').trim())
    .filter(Boolean)
    .join(' ')
    .substring(0, 3000);
}

const transcript = cleanVtt(captionOutput);

let text_source = 'none';
let available_text = '';

if (transcript.length > 50) {
  text_source = 'captions';
  available_text = transcript;
} else if (hasDescription) {
  text_source = 'description';
  available_text = video.description;
} else {
  text_source = 'visual_only';
  available_text = '';
}

console.log(`Video: ${video.title}`);
console.log(`Text source: ${text_source} (${available_text.length} chars)`);

return [{
  json: {
    ...data,
    current_video: video,
    text_source,
    available_text,
    needs_visual_analysis: text_source === 'visual_only'
  }
}];

// Merge visual analysis result back into main data
const data = $('Decide Path').first().json;
let analysis_text = '';

try {
  const raw = $input.first().json.stdout || '{}';
  // Find JSON in output
  const match = raw.match(/\{[\s\S]+\}/);
  if (match) {
    const analysis = JSON.parse(match[0]);
    analysis_text = analysis.description || 
                    JSON.stringify(analysis).substring(0, 1000);
  }
} catch(e) {
  analysis_text = 'Visual analysis unavailable';
}

return [{
  json: {
    ...data,
    available_text: analysis_text,
    text_source: 'visual_analysis'
  }
}];

// Merge all paths back together
// Both text path and visual path end here
const items = $input.all();
return items;

