// Parse AI script output
const aiResponse = $input.first().json;
const data = $('Merge Paths').first().json;

let script = {};
try {
  let content = aiResponse.choices[0].message.content;
  // Clean markdown code blocks if present
  content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  script = JSON.parse(content);
} catch(e) {
  script = {
    title: data.current_video.title + ' (Inspired)',
    hook: 'AI script generation failed - raw output: ' + 
          (aiResponse.choices?.[0]?.message?.content || 'no output'),
    segments: [],
    conclusion: '',
    cta: '',
    instagram_caption: '',
    tiktok_caption: '',
    twitter: ''
  };
}

return [{
  json: {
    ...data,
    script,
    completed_at: new Date().toISOString()
  }
}];

