// Build final output document
const data = $('Parse Script').first().json;
const script = data.script;

// Parse music suggestion
let music = {};
try {
  let musicContent = $('Music Finder Agent').first().json.choices[0].message.content;
  musicContent = musicContent.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  music = JSON.parse(musicContent);
} catch(e) {
  music = { mood: 'calm', genre: 'ambient', description: 'Calm background music' };
}

// Parse footage results
const footageVideos = [];
try {
  const footageRaw = $('Footage Search').first().json.stdout || '';
  for (const line of footageRaw.split('\n')) {
    if (!line.trim()) continue;
    try {
      const v = JSON.parse(line);
      footageVideos.push({
        title: v.title,
        url: v.url || `https://youtube.com/watch?v=${v.id}`,
        channel: v.channel || v.uploader
      });
    } catch(e) {}
  }
} catch(e) {}

// Build markdown document
const md = `# ${script.title || data.current_video.title}

Generated: ${new Date().toISOString()}
Source: ${data.current_video.url}
Text source: ${data.text_source}

---

## Hook
${script.hook || ''}

## Script
${(script.segments || []).map((s, i) => 
  `### ${i+1}. ${s.title || 'Segment ' + (i+1)}\n${s.narration || ''}\n\n> 🎬 B-Roll: ${s.broll_suggestion || ''}\n`
).join('\n')}

## Conclusion
${script.conclusion || ''}

**CTA:** ${script.cta || ''}

---

## Platform Captions

**Instagram:** ${script.instagram_caption || ''}

**TikTok:** ${script.tiktok_caption || ''}

**Twitter/X:** ${script.twitter || ''}

---

## Music Suggestion
- **Mood:** ${music.mood || ''}
- **Genre:** ${music.genre || ''}
- **Description:** ${music.description || ''}
- **Search Freesound:** https://freesound.org/search/?q=${encodeURIComponent(music.freesound_search || music.genre || 'ambient')}
- **Search Pixabay:** https://pixabay.com/music/search/${encodeURIComponent(music.pixabay_search || music.genre || 'ambient')}/

---

## Reference Footage
${footageVideos.slice(0, 5).map(v => `- [${v.title}](${v.url}) — ${v.channel}`).join('\n')}
`;

return [{
  json: {
    run_id: data.run_id,
    user_id: data.user_id,
    source_video: data.current_video,
    script,
    music,
    footage: footageVideos,
    markdown: md,
    text_source: data.text_source
  }
}];
